-- Empty prospective canonical delegation; no legacy adoption or permission grants.
create table canonical_delegations(
 id uuid primary key,organization_id text not null,legal_entity_id text not null,delegator_user_id uuid not null references users(id),definition jsonb not null,
 request_id uuid not null,request_fingerprint text not null,reason text not null check(length(btrim(reason))between 1 and 1000),operation_id text not null,created_at timestamptz not null default clock_timestamp(),
 foreign key(organization_id,legal_entity_id)references legal_entities(organization_id,id),unique(organization_id,legal_entity_id,delegator_user_id,request_id)
);
create table canonical_delegation_revocations(id uuid primary key,delegation_id uuid not null unique references canonical_delegations(id),actor_id uuid not null references users(id),active_role text not null,request_id uuid not null,request_fingerprint text not null,reason text not null check(length(btrim(reason))between 1 and 1000),operation_id text not null,created_at timestamptz not null default clock_timestamp());
create table canonical_delegation_bindings(id uuid primary key,origin text not null check(origin in('Work','Material','Creation','Leave')),instance_id uuid not null,stage integer not null check(stage between 0 and 9),delegation_id uuid not null references canonical_delegations(id),created_at timestamptz not null default clock_timestamp(),unique(origin,instance_id,stage));
create table canonical_delegation_decisions(origin text not null,transition_id uuid not null,binding_id uuid not null references canonical_delegation_bindings(id),actor_id uuid not null references users(id),created_at timestamptz not null default clock_timestamp(),primary key(origin,transition_id));
do $$declare t text;begin foreach t in array array['canonical_delegations','canonical_delegation_revocations','canonical_delegation_bindings','canonical_delegation_decisions']loop execute format('create trigger immutable_%I before update or delete on %I for each row execute function reject_commercial_draft_rewrite()',t,t);end loop;end $$;
create index canonical_delegation_match on canonical_delegations(organization_id,legal_entity_id,delegator_user_id,created_at);
create function canonical_delegation_source(k text,iid uuid)returns table(org text,legal text,worker text,requester uuid,stages jsonb,created timestamptz,source_xid text)language sql stable as $$
 select i.organization_id,i.legal_entity_id,i.employee_id,i.requester_user_id,p.definition->'stages',i.created_at,i.xmin::text from work_approval_instances i join work_approval_policy_versions p on p.id=i.policy_id where k='Work'and i.id=iid
 union all select i.organization_id,i.legal_entity_id,i.employee_id,i.requester_user_id,p.definition->'stages',i.created_at,i.xmin::text from assignment_approval_instances i join assignment_approval_policies p on p.id=i.policy_id where k=case when i.operation_kind='Creation'then'Creation'else'Material'end and i.id=iid
 union all select i.organization_id,i.legal_entity_id,i.employee_id,i.requester_user_id,p.definition->'stages',i.created_at,i.xmin::text from leave_approval_instances i join leave_approval_policies p on p.id=i.policy_id where k='Leave'and i.id=iid;
$$;
create function canonical_delegation_account(uid uuid,role_arg text,org_arg text,legal_arg text,worker_arg text,kind_arg text)returns boolean language plpgsql stable as $$
declare u record;e employees;keys text[];k text;begin
 select u0.*,cd.id country_director_id into u from users u0 left join employees a on a.id=u0.employee_record_id left join country_directors cd on cd.id=a.primary_country_director_id and(lower(a.designation)in('country director','regional lead','director')or lower(a.department)='regional leadership')where u0.id=uid and u0.status='Active';if u.id is null or not exists(select 1 from user_roles ur join roles r on r.id=ur.role_id where ur.user_id=uid and r.name=role_arg)or not exists(select 1 from user_organization_scopes where user_id=uid and organization_id=org_arg and legal_entity_id=legal_arg and active)or exists(select 1 from employees where id=u.employee_record_id and status='Exited')then return false;end if;
 keys=array['employees.view','approvals.view','notifications.view']||case when kind_arg='Work'then array['timesheets.approve','timesheets.submit','projects.view']when kind_arg='Leave'then array['leave.self_service','leave.approve']else array['allocations.manage','allocations.view','projects.view']end;
 foreach k in array keys loop if not exists(select 1 from role_permissions where role_name=role_arg and permission_key=k and enabled)and not exists(select 1 from user_permission_grants where user_id=uid and permission_key=k)then return false;end if;end loop;
 if worker_arg is null then return true;end if;select * into e from employees where id=worker_arg and organization_id=org_arg and legal_entity_id=legal_arg;if e.id is null then return false;end if;
 if role_arg in('Admin','HR')then return true;end if;
 if role_arg='Employee'then return e.id=u.employee_record_id or e.employee_id=u.employee_id;end if;
 if role_arg='TeamLead'then
  if kind_arg in('Work','Leave')then return e.reporting_manager_id in(u.employee_record_id,u.employee_id);end if;
  return e.id=u.employee_record_id or e.employee_id=u.employee_id or exists(with recursive chain as(select id from employees where reporting_manager_id in(u.employee_record_id,u.employee_id)and organization_id=org_arg and legal_entity_id=legal_arg union select x.id from employees x join chain c on x.reporting_manager_id=c.id where x.organization_id=org_arg and x.legal_entity_id=legal_arg)select 1 from chain where id=e.id);
 end if;
 if role_arg='CountryDirector'then return e.primary_country_director_id=u.country_director_id or exists(select 1 from employee_country_director_map where employee_id=e.id and country_director_id=u.country_director_id);end if;
 if role_arg='ProjectManager'then return e.id=u.employee_record_id or e.employee_id=u.employee_id or exists(select 1 from project_allocations a join projects p on p.id=a.project_id where a.employee_id=e.id and p.organization_id=org_arg and p.legal_entity_id=legal_arg and p.manager_id in(u.employee_record_id,u.employee_id));end if;return false;
end $$;
create function canonical_delegation_valid(d canonical_delegations)returns boolean language plpgsql stable as $$declare x jsonb;worker text;kind text;begin
 x=d.definition;
 if jsonb_typeof(x)is distinct from'object'or(select count(*)from jsonb_object_keys(x))<>8 or not(x?&array['delegateUserId','role','workerIds','sourceKinds','clockBasis','cohort','startsAt','endsAt'])or x->>'clockBasis'<>'UTC'or x->>'cohort'<>'NewInstances'or x->>'delegateUserId'=d.delegator_user_id::text or(x->>'delegateUserId')!~'^[a-f0-9-]{36}$'or length(x->>'role')not between 1 and 100 or jsonb_typeof(x->'workerIds')is distinct from'array'or jsonb_array_length(x->'workerIds')not between 1 and 200 or jsonb_typeof(x->'sourceKinds')is distinct from'array'or jsonb_array_length(x->'sourceKinds')not between 1 and 4 or(x->>'startsAt')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'or(x->>'endsAt')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'or(x->>'startsAt')::timestamptz>=(x->>'endsAt')::timestamptz then return false;end if;
 if(select count(distinct v)from jsonb_array_elements_text(x->'workerIds')v)<>jsonb_array_length(x->'workerIds')or(select count(distinct v)from jsonb_array_elements_text(x->'sourceKinds')v)<>jsonb_array_length(x->'sourceKinds')then return false;end if;
 for kind in select jsonb_array_elements_text(x->'sourceKinds')loop if kind not in('Creation','Leave','Material','Work')then return false;end if;
 for worker in select jsonb_array_elements_text(x->'workerIds')loop if not canonical_delegation_account(d.delegator_user_id,x->>'role',d.organization_id,d.legal_entity_id,worker,kind)or not canonical_delegation_account((x->>'delegateUserId')::uuid,x->>'role',d.organization_id,d.legal_entity_id,worker,kind)then return false;end if;end loop;end loop;return true;
 exception when others then return false;
end $$;
create function guard_canonical_delegation()returns trigger language plpgsql as $$declare ctx jsonb;d canonical_delegations;s record;begin
 begin ctx=nullif(current_setting('workos.canonical_delegation_context',true),'')::jsonb;exception when others then ctx=null;end;
 if tg_table_name='canonical_delegations'then
  if ctx is null or ctx->>'actorId'is distinct from new.delegator_user_id::text or ctx->>'organizationId'is distinct from new.organization_id or ctx->>'legalEntityId'is distinct from new.legal_entity_id or ctx->>'activeRole'is distinct from new.definition->>'role'or ctx->>'operationId'is distinct from new.operation_id or new.created_at<statement_timestamp()or new.created_at>clock_timestamp()or(new.definition->>'startsAt')::timestamptz<new.created_at or not canonical_delegation_valid(new)then raise exception 'Adopt only explicit prospective owned delegation with both current roles/scopes.'using errcode='CDG01';end if;
  if exists(select 1 from canonical_delegations prior_d where prior_d.organization_id=new.organization_id and prior_d.legal_entity_id=new.legal_entity_id and prior_d.delegator_user_id=new.delegator_user_id and prior_d.definition->>'role'=new.definition->>'role'and not exists(select 1 from canonical_delegation_revocations where delegation_id=prior_d.id)and tstzrange((prior_d.definition->>'startsAt')::timestamptz,(prior_d.definition->>'endsAt')::timestamptz,'[)')&&tstzrange((new.definition->>'startsAt')::timestamptz,(new.definition->>'endsAt')::timestamptz,'[)')and prior_d.definition->'workerIds'?|array(select jsonb_array_elements_text(new.definition->'workerIds'))and prior_d.definition->'sourceKinds'?|array(select jsonb_array_elements_text(new.definition->'sourceKinds')))then raise exception 'Overlapping delegation has ambiguous authority.'using errcode='CDG02';end if;
 elsif tg_table_name='canonical_delegation_revocations'then
  select * into d from canonical_delegations where id=new.delegation_id;
  if ctx is null or d.id is null or ctx->>'organizationId'is distinct from d.organization_id or ctx->>'legalEntityId'is distinct from d.legal_entity_id or new.actor_id<>d.delegator_user_id or ctx->>'actorId'is distinct from new.actor_id::text or ctx->>'activeRole'is distinct from new.active_role or ctx->>'operationId'is distinct from new.operation_id or new.created_at<statement_timestamp()or new.created_at>clock_timestamp()or not exists(select 1 from users u join user_roles ur on ur.user_id=u.id join roles r on r.id=ur.role_id join user_organization_scopes sc on sc.user_id=u.id where u.id=new.actor_id and u.status='Active'and r.name=new.active_role and sc.organization_id=d.organization_id and sc.legal_entity_id=d.legal_entity_id and sc.active)then raise exception 'Only the actual current owner may append revocation.'using errcode='CDG01';end if;
 elsif tg_table_name='canonical_delegation_bindings'then
  select * into s from canonical_delegation_source(new.origin,new.instance_id);select * into d from canonical_delegations where id=new.delegation_id;
  if s.source_xid is distinct from pg_current_xact_id()::text or d.id is null or d.organization_id<>s.org or d.legal_entity_id<>s.legal or d.delegator_user_id::text is distinct from s.stages->new.stage->>'userId'or d.definition->>'role'is distinct from s.stages->new.stage->>'role'or not(d.definition->'workerIds'?s.worker)or not(d.definition->'sourceKinds'?new.origin)or d.created_at>s.created or s.created<(d.definition->>'startsAt')::timestamptz or s.created>=(d.definition->>'endsAt')::timestamptz or exists(select 1 from canonical_delegation_revocations where delegation_id=d.id)or not canonical_delegation_valid(d)then raise exception 'Only a new current transaction instance may bind exact prospective delegation.'using errcode='CDG01';end if;
 end if;return new;
end $$;
create trigger guarded_canonical_delegations before insert on canonical_delegations for each row execute function guard_canonical_delegation();
create trigger guarded_canonical_revocations before insert on canonical_delegation_revocations for each row execute function guard_canonical_delegation();
create trigger guarded_canonical_bindings before insert on canonical_delegation_bindings for each row execute function guard_canonical_delegation();
create function bind_canonical_delegation()returns trigger language plpgsql as $$declare k text;s record;x jsonb;n integer;d canonical_delegations;begin
 if tg_table_name='work_approval_instances'then k='Work';elsif tg_table_name='leave_approval_instances'then k='Leave';else k=case when new.operation_kind='Creation'then'Creation'else'Material'end;end if;
 select * into s from canonical_delegation_source(k,new.id);
 for x,n in select value,ordinality::integer-1 from jsonb_array_elements(s.stages)with ordinality loop
  for d in select * from canonical_delegations cfg where cfg.organization_id=s.org and cfg.legal_entity_id=s.legal and cfg.delegator_user_id::text=x->>'userId'and cfg.definition->>'role'=x->>'role'and cfg.definition->'workerIds'?s.worker and cfg.definition->'sourceKinds'?k and cfg.created_at<=s.created and(cfg.definition->>'startsAt')::timestamptz<=s.created and(cfg.definition->>'endsAt')::timestamptz>s.created and not exists(select 1 from canonical_delegation_revocations where delegation_id=cfg.id)loop
   if canonical_delegation_valid(d)and canonical_delegation_instance_account(d.delegator_user_id,d.definition->>'role',k,new.id)and canonical_delegation_instance_account((d.definition->>'delegateUserId')::uuid,d.definition->>'role',k,new.id)and(d.definition->>'delegateUserId')::uuid<>s.requester and not exists(select 1 from users where id=(d.definition->>'delegateUserId')::uuid and(employee_record_id=s.worker or employee_id=s.worker))then insert into canonical_delegation_bindings values(gen_random_uuid(),k,new.id,n,d.id,clock_timestamp());end if;
  end loop;
 end loop;return null;
end $$;
create trigger retained_work_delegation after insert on work_approval_instances for each row execute function bind_canonical_delegation();
create trigger retained_assignment_delegation after insert on assignment_approval_instances for each row execute function bind_canonical_delegation();
create trigger retained_leave_delegation after insert on leave_approval_instances for each row execute function bind_canonical_delegation();
create function canonical_delegation_instance_account(uid uuid,role_arg text,k text,iid uuid)returns boolean language plpgsql stable as $$declare s record;u users;project text;sheet uuid;cd text;begin
 select * into s from canonical_delegation_source(k,iid);if s.org is null or not canonical_delegation_account(uid,role_arg,s.org,s.legal,s.worker,k)then return false;end if;select * into u from users where id=uid;
 if k='Work'and role_arg='ProjectManager'then select timesheet_id into sheet from work_approval_instances where id=iid;return exists(select 1 from timesheet_entries e join projects p on p.id=e.project_id where e.timesheet_id=sheet and p.organization_id=s.org and p.legal_entity_id=s.legal and p.manager_id in(u.employee_record_id,u.employee_id));end if;
 if k not in('Material','Creation')then return true;end if;select project_id into project from assignment_approval_instances where id=iid;if not exists(select 1 from projects where id=project and organization_id=s.org and legal_entity_id=s.legal)then return false;end if;
 if role_arg in('Admin','HR')then return true;elsif role_arg in('Employee','TeamLead')then return exists(select 1 from project_allocations where project_id=project and employee_id in(u.employee_record_id,u.employee_id));elsif role_arg='ProjectManager'then return exists(select 1 from projects where id=project and manager_id in(u.employee_record_id,u.employee_id));elsif role_arg='CountryDirector'then select a.primary_country_director_id into cd from employees a where a.id=u.employee_record_id and(lower(a.designation)in('country director','regional lead','director')or lower(a.department)='regional leadership');return exists(select 1 from project_allocations a join employees e on e.id=a.employee_id left join employee_country_director_map m on m.employee_id=e.id where a.project_id=project and(e.primary_country_director_id=cd or m.country_director_id=cd));end if;return false;
end $$;
create function canonical_delegation_eligible(b canonical_delegation_bindings,at_time timestamptz)returns boolean language plpgsql stable as $$declare d canonical_delegations;s record;begin
 select * into d from canonical_delegations where id=b.delegation_id;select * into s from canonical_delegation_source(b.origin,b.instance_id);
 return coalesce(d.delegator_user_id::text=s.stages->b.stage->>'userId'and d.definition->>'role'=s.stages->b.stage->>'role'and at_time>=(d.definition->>'startsAt')::timestamptz and at_time<(d.definition->>'endsAt')::timestamptz and not exists(select 1 from canonical_delegation_revocations where delegation_id=d.id and created_at<=at_time)and canonical_delegation_instance_account(d.delegator_user_id,d.definition->>'role',b.origin,b.instance_id)and canonical_delegation_instance_account((d.definition->>'delegateUserId')::uuid,d.definition->>'role',b.origin,b.instance_id)and(d.definition->>'delegateUserId')::uuid<>s.requester and not exists(select 1 from users where id=(d.definition->>'delegateUserId')::uuid and(employee_record_id=s.worker or employee_id=s.worker)),false);
end $$;
create function canonical_stage_actor(k text,iid uuid,stage_arg integer,named uuid,actor uuid,role_arg text)returns boolean language sql stable as $$select actor=named or exists(select 1 from canonical_delegation_bindings b join canonical_delegations d on d.id=b.delegation_id where b.origin=k and b.instance_id=iid and b.stage=stage_arg and d.delegator_user_id=named and d.definition->>'delegateUserId'=actor::text and d.definition->>'role'=role_arg and canonical_delegation_eligible(b,clock_timestamp()));$$;
create function canonical_stage_recipients(k text,iid uuid,stage_arg integer,named uuid,at_time timestamptz)returns uuid[]language sql stable as $$select array(select distinct x from(select named x union all select(d.definition->>'delegateUserId')::uuid from canonical_delegation_bindings b join canonical_delegations d on d.id=b.delegation_id where b.origin=k and b.instance_id=iid and b.stage=stage_arg and d.delegator_user_id=named and canonical_delegation_eligible(b,at_time))q order by x);$$;
create function retain_canonical_delegate_decision()returns trigger language plpgsql as $$declare k text;s record;b canonical_delegation_bindings;begin
 k=case when tg_table_name='work_approval_transitions'then'Work'when tg_table_name='leave_approval_transitions'then'Leave'else(select case when operation_kind='Creation'then'Creation'else'Material'end from assignment_approval_instances where id=new.instance_id)end;select * into s from canonical_delegation_source(k,new.instance_id);
 if new.actor_id::text<>s.stages->new.stage->>'userId'then
  select b0.* into b from canonical_delegation_bindings b0 join canonical_delegations d on d.id=b0.delegation_id where b0.origin=k and b0.instance_id=new.instance_id and b0.stage=new.stage and d.definition->>'delegateUserId'=new.actor_id::text and canonical_delegation_eligible(b0,clock_timestamp());
  if b.id is null then raise exception 'Retained current actual delegate binding required.'using errcode='CDG03';end if;
  insert into canonical_delegation_decisions values(k,new.id,b.id,new.actor_id,clock_timestamp());
 end if;return null;
end $$;
create trigger retained_work_delegate_decision after insert on work_approval_transitions for each row execute function retain_canonical_delegate_decision();
create trigger retained_assignment_delegate_decision after insert on assignment_approval_transitions for each row execute function retain_canonical_delegate_decision();
create trigger retained_leave_delegate_decision after insert on leave_approval_transitions for each row execute function retain_canonical_delegate_decision();
create or replace function guard_work_approval_append()returns trigger language plpgsql as $$
declare ctx jsonb;i work_approval_instances;p work_approval_policy_versions;last_stage integer;n integer;terminal boolean;s work_submission_evidence;
begin
 begin ctx=nullif(current_setting('workos.work_approval_context',true),'')::jsonb;exception when others then ctx=null;end;
 if ctx is null or not exists(select 1 from users where id=(ctx->>'actorId')::uuid and status='Active')then raise exception 'Use the scoped work-approval command.'using errcode='WGA01';end if;
 if tg_table_name='work_approval_policy_versions'then
  select * into p from work_approval_policy_versions where organization_id=new.organization_id and legal_entity_id=new.legal_entity_id order by sequence desc limit 1;
  if ctx->>'organizationId'is distinct from new.organization_id or ctx->>'legalEntityId'is distinct from new.legal_entity_id or ctx->>'actorId'is distinct from new.actor_id::text or ctx->>'activeRole'is distinct from new.active_role or new.sequence<>coalesce(p.sequence,0)+1 or new.effective_from<(clock_timestamp()at time zone'UTC')::date or(p.id is not null and new.effective_from<=p.effective_from)then raise exception 'Policy must append prospectively in its scoped sequence.'using errcode='WGA02';end if;return new;
 end if;
 if tg_table_name='work_approval_templates'then select * into p from work_approval_policy_versions where id=new.policy_id;
  if ctx->>'organizationId'is distinct from p.organization_id or ctx->>'legalEntityId'is distinct from p.legal_entity_id then raise exception 'Template policy scope unavailable.'using errcode='WGA01';end if;return new;
 end if;
 if tg_table_name='work_approval_instances'then
  select * into s from work_submission_evidence where id=new.submission_id;select * into p from work_approval_policy_versions where id=new.policy_id;
  if ctx->>'organizationId'is distinct from new.organization_id or ctx->>'legalEntityId'is distinct from new.legal_entity_id or s.timesheet_id<>new.timesheet_id or s.organization_id<>new.organization_id or s.legal_entity_id<>new.legal_entity_id or s.sequence<>new.submission_sequence or s.actor_id<>new.requester_user_id or p.organization_id<>new.organization_id or p.legal_entity_id<>new.legal_entity_id or not(p.definition->'workerIds'?new.employee_id)or not exists(select 1 from timesheets where id=new.timesheet_id and employee_id=new.employee_id and status='Submitted')or new.source_token<>encode(digest(new.source_canonical,'sha256'),'hex')then raise exception 'Work approval requires exact scoped submitted evidence.'using errcode='WGA01';end if;return new;
 end if;
 if tg_table_name='work_approval_reads'then
  if ctx->>'actorId'is distinct from new.user_id::text or not exists(select 1 from work_approval_recipients r join work_approval_events e on e.id=r.event_id join work_approval_instances w on w.id=e.instance_id where r.id=new.recipient_id and r.user_id=new.user_id and r.in_app and w.organization_id=ctx->>'organizationId'and w.legal_entity_id=ctx->>'legalEntityId')then raise exception 'Read only your scoped in-app receipt.'using errcode='WGA01';end if;return new;
 end if;
 if tg_table_name='work_approval_recipients'then select w.* into i from work_approval_instances w join work_approval_events e on e.instance_id=w.id where e.id=new.event_id;
 else select * into i from work_approval_instances where id=new.instance_id;end if;
 if i.id is null or ctx->>'organizationId'is distinct from i.organization_id or ctx->>'legalEntityId'is distinct from i.legal_entity_id then raise exception 'Approval evidence scope is unavailable.'using errcode='WGA01';end if;
 if tg_table_name='work_approval_transitions'then
  select * into p from work_approval_policy_versions where id=i.policy_id;
  select count(*),coalesce(bool_or(decision='Rejected'),false)into n,terminal from work_approval_transitions where instance_id=i.id;
  if terminal or new.sequence<>n+1 or new.stage<>n or new.stage>=jsonb_array_length(p.definition->'stages')or not canonical_stage_actor('Work',i.id,new.stage,(p.definition->'stages'->new.stage->>'userId')::uuid,new.actor_id,new.active_role)or new.active_role<>p.definition->'stages'->new.stage->>'role'or ctx->>'actorId'is distinct from new.actor_id::text or ctx->>'activeRole'is distinct from new.active_role or ctx->>'operationId'is distinct from new.operation_id or new.actor_id=i.requester_user_id or not exists(select 1 from user_roles ur join roles r on r.id=ur.role_id where ur.user_id=new.actor_id and r.name=new.active_role) or exists(select 1 from users where id=new.actor_id and employee_record_id=i.employee_id)or not exists(select 1 from timesheets t where t.id=i.timesheet_id and t.status='Submitted')then raise exception 'Only the current authorized stage can append a decision.'using errcode='WGA03';end if;
 end if;return new;
end $$;

create or replace function guard_assignment_approval_append()returns trigger language plpgsql as $$
declare ctx jsonb;i assignment_approval_instances;p assignment_approval_policies;a project_allocations;t assignment_approval_transitions;n integer;terminal boolean;v uuid;
begin
 begin ctx=nullif(current_setting('workos.assignment_approval_context',true),'')::jsonb;exception when others then ctx=null;end;
 if ctx is null or not exists(select 1 from users u join user_roles ur on ur.user_id=u.id join roles r on r.id=ur.role_id join user_organization_scopes s on s.user_id=u.id where u.id=(ctx->>'actorId')::uuid and u.status='Active'and r.name=ctx->>'activeRole'and s.organization_id=ctx->>'organizationId'and s.legal_entity_id=ctx->>'legalEntityId'and s.active)then raise exception 'Use the scoped assignment approval command.'using errcode='ASA02';end if;
 if tg_table_name='assignment_approval_policies'then
  select * into p from assignment_approval_policies where organization_id=new.organization_id and legal_entity_id=new.legal_entity_id order by sequence desc limit 1;
  if not(new.definition?'creationRequired')and p.definition?'creationRequired'then new.definition=new.definition||jsonb_build_object('creationRequired',p.definition->'creationRequired');end if;
  if new.organization_id is distinct from ctx->>'organizationId'or new.legal_entity_id is distinct from ctx->>'legalEntityId'or new.actor_id::text is distinct from ctx->>'actorId'or new.active_role is distinct from ctx->>'activeRole'or new.sequence<>coalesce(p.sequence,0)+1 or new.effective_from<(clock_timestamp()at time zone'UTC')::date or(p.id is not null and new.effective_from<=p.effective_from)then raise exception 'Append the current prospective policy sequence.'using errcode='ASA02';end if;return new;
 elsif tg_table_name='assignment_approval_templates'then select * into p from assignment_approval_policies where id=new.policy_id;if p.organization_id is distinct from ctx->>'organizationId'or p.legal_entity_id is distinct from ctx->>'legalEntityId'then raise exception 'Template scope unavailable.'using errcode='ASA02';end if;return new;
 elsif tg_table_name='assignment_approval_instances'then
  if new.operation_kind='Creation'then
   select * into p from assignment_material_policy(new.organization_id,new.legal_entity_id,new.employee_id);
   if new.organization_id is distinct from ctx->>'organizationId'or new.legal_entity_id is distinct from ctx->>'legalEntityId'or new.requester_user_id::text is distinct from ctx->>'actorId'or new.active_role is distinct from ctx->>'activeRole'or new.operation_id is distinct from ctx->>'operationId'or p.id is null or new.policy_id is distinct from p.id or p.definition->'creationRequired'is distinct from'true'::jsonb or new.before_snapshot is distinct from'null'::jsonb or new.source_version_id is not null or not valid_assignment_creation_definition(new.proposed_definition)or exists(select 1 from project_allocations where id=new.assignment_id)or exists(select 1 from assignment_versions where assignment_id=new.assignment_id)or new.source_token<>encode(digest(new.source_canonical,'sha256'),'hex')or new.source_canonical::jsonb is distinct from jsonb_build_object('operationKind','Creation','assignmentId',new.assignment_id,'employeeId',new.employee_id,'projectId',new.project_id,'before',null,'sourceRevision',new.source_revision,'sourceVersionId',null,'policyId',new.policy_id,'definition',new.proposed_definition)then raise exception 'Creation request requires exact absent scoped source and adopted policy.'using errcode='ASA02';end if;return new;
  end if;
  select * into a from project_allocations where id=new.assignment_id and organization_id=new.organization_id and legal_entity_id=new.legal_entity_id;
  select * into p from assignment_material_policy(new.organization_id,new.legal_entity_id,new.employee_id);
  select id into v from assignment_versions where assignment_id=new.assignment_id order by sequence desc limit 1;
  if a.id is null or new.organization_id is distinct from ctx->>'organizationId'or new.legal_entity_id is distinct from ctx->>'legalEntityId'or new.requester_user_id::text is distinct from ctx->>'actorId'or new.active_role is distinct from ctx->>'activeRole'or new.operation_id is distinct from ctx->>'operationId'or new.employee_id<>a.employee_id or new.project_id<>a.project_id or new.policy_id is distinct from p.id or new.source_revision<>resource_assignment_revision(a)or new.before_snapshot<>assignment_version_snapshot(a)or new.source_version_id is distinct from v or not assignment_requires_approval(new.before_snapshot,new.before_snapshot||new.proposed_definition,p.definition)or new.source_token<>encode(digest(new.source_canonical,'sha256'),'hex')then raise exception 'Proposal requires exact current scoped material source/policy.'using errcode='ASA02';end if;return new;
 elsif tg_table_name='assignment_approval_reads'then
  if ctx->>'actorId'is distinct from new.user_id::text or not exists(select 1 from assignment_approval_recipients r join assignment_approval_events e on e.id=r.event_id join assignment_approval_instances w on w.id=e.instance_id where r.id=new.recipient_id and r.user_id=new.user_id and r.in_app and w.organization_id=ctx->>'organizationId'and w.legal_entity_id=ctx->>'legalEntityId')then raise exception 'Read only your scoped recipient evidence.'using errcode='ASA02';end if;return new;
 elsif tg_table_name='assignment_approval_deliveries'then select w.* into i from assignment_approval_instances w join assignment_approval_events e on e.instance_id=w.id join assignment_approval_recipients r on r.event_id=e.id where r.id=new.recipient_id and r.in_app;
 elsif tg_table_name='assignment_approval_recipients'then select w.* into i from assignment_approval_instances w join assignment_approval_events e on e.instance_id=w.id where e.id=new.event_id;
 else select * into i from assignment_approval_instances where id=new.instance_id;end if;
 if i.id is null or i.organization_id is distinct from ctx->>'organizationId'or i.legal_entity_id is distinct from ctx->>'legalEntityId'then raise exception 'Approval source scope unavailable.'using errcode='ASA02';end if;
 if tg_table_name='assignment_approval_transitions'then
  select * into p from assignment_approval_policies where id=i.policy_id;
  select count(*),coalesce(bool_or(decision='Rejected'),false)into n,terminal from assignment_approval_transitions where instance_id=i.id;
  if terminal or new.sequence<>n+1 or new.stage<>n or new.stage>=jsonb_array_length(p.definition->'stages')or not canonical_stage_actor(case when i.operation_kind='Creation'then'Creation'else'Material'end,i.id,new.stage,(p.definition->'stages'->new.stage->>'userId')::uuid,new.actor_id,new.active_role)or new.active_role is distinct from p.definition->'stages'->new.stage->>'role'or ctx->>'actorId'is distinct from new.actor_id::text or ctx->>'activeRole'is distinct from new.active_role or ctx->>'operationId'is distinct from new.operation_id or new.actor_id=i.requester_user_id or exists(select 1 from users where id=new.actor_id and employee_record_id=i.employee_id)or(i.operation_kind='MaterialChange'and not exists(select 1 from project_allocations source_row where source_row.id=i.assignment_id and source_row.organization_id=i.organization_id and source_row.legal_entity_id=i.legal_entity_id and resource_assignment_revision(source_row)=i.source_revision))or(i.operation_kind='Creation'and(exists(select 1 from project_allocations where id=i.assignment_id)or exists(select 1 from assignment_versions where assignment_id=i.assignment_id)))then raise exception 'Only the current named stage and exact source can decide.'using errcode='ASA03';end if;
 end if;return new;
end $$;

create or replace function guard_leave_approval_append()returns trigger language plpgsql as $$
declare ctx jsonb;i leave_approval_instances;p leave_approval_policies;prior leave_approval_instances;lr leave_requests;n integer;terminal boolean;e employees;s text;
begin
 begin ctx=nullif(current_setting('workos.leave_approval_context',true),'')::jsonb;exception when others then ctx=null;end;
 if ctx is null or not exists(select 1 from users u join user_roles ur on ur.user_id=u.id join roles r on r.id=ur.role_id join user_organization_scopes sc on sc.user_id=u.id where u.id=(ctx->>'actorId')::uuid and u.status='Active'and r.name=ctx->>'activeRole'and sc.organization_id=ctx->>'organizationId'and sc.legal_entity_id=ctx->>'legalEntityId'and sc.active)then raise exception 'Use the current scoped leave approval command.'using errcode='LGA01';end if;
 if tg_table_name='leave_approval_policies'then
  select * into p from leave_approval_policies where organization_id=new.organization_id and legal_entity_id=new.legal_entity_id order by sequence desc limit 1;
  if new.organization_id is distinct from ctx->>'organizationId'or new.legal_entity_id is distinct from ctx->>'legalEntityId'or new.actor_id::text is distinct from ctx->>'actorId'or new.active_role is distinct from ctx->>'activeRole'or new.sequence<>coalesce(p.sequence,0)+1 or new.effective_from<(clock_timestamp()at time zone'UTC')::date or(p.id is not null and new.effective_from<=p.effective_from)or new.created_at<statement_timestamp()or new.created_at>clock_timestamp()then raise exception 'Append the exact prospective policy.'using errcode='LGA02';end if;return new;
 elsif tg_table_name='leave_approval_templates'then
  select * into p from leave_approval_policies where id=new.policy_id;
  if p.organization_id is distinct from ctx->>'organizationId'or p.legal_entity_id is distinct from ctx->>'legalEntityId'or not exists(select 1 from jsonb_array_elements(p.definition->'templates')t where t->>'key'=new.event_key and t->>'subject'=new.subject and t->>'body'=new.body)or new.locale is distinct from p.definition->>'locale'then raise exception 'Use the exact retained template.'using errcode='LGA01';end if;return new;
 elsif tg_table_name='leave_approval_instances'then
  select * into lr from leave_requests where id=new.request_id;select * into e from employees where id=lr.employee_id;
  select * into prior from leave_approval_instances where request_id=new.request_id order by sequence desc limit 1;
  if prior.id is null then select * into p from leave_selected_approval_policy(e.organization_id,e.legal_entity_id,e.id);else select * into p from leave_approval_policies where id=prior.policy_id;end if;
  if lr.id is null or lr.status<>'Submitted'or p.id is null or new.policy_id is distinct from p.id or new.sequence<>coalesce(prior.sequence,0)+1 or new.employee_id<>lr.employee_id or new.organization_id<>e.organization_id or new.legal_entity_id<>e.legal_entity_id or new.organization_id is distinct from ctx->>'organizationId'or new.legal_entity_id is distinct from ctx->>'legalEntityId'or new.actor_id::text is distinct from ctx->>'actorId'or new.active_role is distinct from ctx->>'activeRole'or new.operation_id is distinct from ctx->>'operationId'or new.requester_user_id is distinct from coalesce(prior.requester_user_id,new.actor_id)or new.source_snapshot is distinct from leave_source_snapshot(lr)or new.source_token<>encode(digest(new.source_canonical,'sha256'),'hex')or new.source_canonical::jsonb is distinct from jsonb_build_object('version','leave-approval/1','policyId',new.policy_id,'requesterUserId',new.requester_user_id,'source',new.source_snapshot)or new.created_at<statement_timestamp()or new.created_at>clock_timestamp()then raise exception 'Retain the exact current leave source, pinned route and actual revision time.'using errcode='LGA02';end if;return new;
 elsif tg_table_name='leave_approval_reads'then
  if ctx->>'actorId'is distinct from new.user_id::text or not exists(select 1 from leave_approval_recipients r join leave_approval_events ev on ev.id=r.event_id join leave_approval_instances w on w.id=ev.instance_id where r.id=new.recipient_id and r.user_id=new.user_id and r.in_app and w.organization_id=ctx->>'organizationId'and w.legal_entity_id=ctx->>'legalEntityId')then raise exception 'Read only the owned scoped recipient.'using errcode='LGA01';end if;return new;
 elsif tg_table_name='leave_approval_deliveries'then select w.* into i from leave_approval_instances w join leave_approval_events ev on ev.instance_id=w.id join leave_approval_recipients r on r.event_id=ev.id where r.id=new.recipient_id and r.in_app;
 elsif tg_table_name='leave_approval_recipients'then select w.* into i from leave_approval_instances w join leave_approval_events ev on ev.instance_id=w.id where ev.id=new.event_id;
 else select * into i from leave_approval_instances where id=new.instance_id;end if;
 if i.id is null or i.organization_id is distinct from ctx->>'organizationId'or i.legal_entity_id is distinct from ctx->>'legalEntityId'then raise exception 'Current leave source scope required.'using errcode='LGA01';end if;
 if tg_table_name='leave_approval_transitions'then
  select * into p from leave_approval_policies where id=i.policy_id;select count(*),coalesce(bool_or(outcome->>'status'<>'Pending'),false)into n,terminal from leave_approval_transitions where instance_id=i.id;
  s=case when new.decision='Rejected'then'Rejected'when new.sequence=jsonb_array_length(p.definition->'stages')then'Approved'else'Pending'end;
  if ctx->>'instanceId'is distinct from i.id::text or terminal or not leave_approval_current(i.id)or new.sequence<>n+1 or new.stage<>n or new.stage>=jsonb_array_length(p.definition->'stages')or not canonical_stage_actor('Leave',i.id,new.stage,(p.definition->'stages'->new.stage->>'userId')::uuid,new.actor_id,new.active_role)or new.active_role is distinct from p.definition->'stages'->new.stage->>'role'or ctx->>'actorId'is distinct from new.actor_id::text or ctx->>'activeRole'is distinct from new.active_role or ctx->>'operationId'is distinct from new.operation_id or new.actor_id=i.requester_user_id or exists(select 1 from users where id=new.actor_id and employee_record_id=i.employee_id)or new.outcome is distinct from jsonb_build_object('status',s,'sequence',new.sequence,'currentStage',case when s='Pending'then new.sequence else null end)or new.created_at<statement_timestamp()or new.created_at>clock_timestamp()then raise exception 'Only the named current stage and exact current source may decide.'using errcode='LGA03';end if;
 elsif tg_table_name='leave_approval_cancellations'then
  select * into lr from leave_requests where id=i.request_id;
  if ctx->>'instanceId'is distinct from i.id::text or i.sequence is distinct from(select max(sequence)from leave_approval_instances where request_id=i.request_id)or lr.status is distinct from new.previous_status or ctx->>'actorId'is distinct from new.actor_id::text or ctx->>'activeRole'is distinct from new.active_role or ctx->>'operationId'is distinct from new.operation_id or ctx->>'action'is distinct from'Cancel'or new.created_at<statement_timestamp()or new.created_at>clock_timestamp()then raise exception 'Retain the actual authorized cancellation.'using errcode='LGA03';end if;
 end if;return new;
end $$;

create or replace function validate_work_approval_commit()returns trigger language plpgsql as $$
declare i work_approval_instances;p work_approval_policy_versions;t timesheets;last work_approval_transitions;ev work_approval_events;seq integer;stage_no integer;key text;worker_user uuid;expected_users uuid[];u uuid;expected_reasons text[];r work_approval_recipients;
begin
 if tg_table_name='work_approval_instances'then i=new;seq=0;stage_no=0;key='approval.action_required';else
  select * into i from work_approval_instances where id=new.instance_id;seq=new.sequence;
 end if;
 select * into p from work_approval_policy_versions where id=i.policy_id;select * into t from timesheets where id=i.timesheet_id;select * into last from work_approval_transitions where instance_id=i.id order by sequence desc limit 1;
 if(last.id is null and t.status<>'Submitted')or(last.decision='Rejected'and t.status<>'Rejected')or(last.decision='Approved'and last.sequence=jsonb_array_length(p.definition->'stages')and t.status<>'Approved')or(last.decision='Approved'and last.sequence<jsonb_array_length(p.definition->'stages')and t.status<>'Submitted')then raise exception 'Source and staged outcome must commit atomically.'using errcode='WGA05';end if;
 if tg_table_name='work_approval_transitions'then
  if new.decision='Rejected'then key='approval.rejected_or_correction_required';stage_no=new.stage;
  elsif new.sequence<jsonb_array_length(p.definition->'stages')then key='approval.action_required';stage_no=new.sequence;
  else key='approval.completed';stage_no=new.stage;end if;
 end if;
 select * into ev from work_approval_events where instance_id=i.id and transition_sequence=seq and event_key=key;
 if not exists(select 1 from approval_records a where a.entity_type='Timesheet'and a.entity_id=t.id::text and a.status=case when last.decision='Rejected'then 'Rejected'when last.decision='Approved'and last.sequence=jsonb_array_length(p.definition->'stages')then 'Approved'else 'Pending'end)then raise exception 'Compatibility and governed approval outcomes must converge.'using errcode='WGA05';end if;
 if key in('approval.completed','approval.rejected_or_correction_required')and not exists(select 1 from work_submission_decisions d where d.submission_id=i.submission_id and d.status=last.decision and d.actor_id=last.actor_id)then raise exception 'Terminal work decision history is required.'using errcode='WGA05';end if;
 if key='approval.completed'and ev.id is null and exists(select 1 from work_approval_notification_failures where instance_id=i.id and transition_sequence=seq)then return null;end if;
 if ev.id is null or ev.stage<>stage_no or not exists(select 1 from work_approval_templates where id=ev.template_id and policy_id=p.id and event_key=key)then raise exception 'The canonical transition event/template must commit once.'using errcode='WGA05';end if;
 if key='approval.action_required'then expected_users=canonical_stage_recipients('Work',i.id,stage_no,(p.definition->'stages'->stage_no->>'userId')::uuid,ev.created_at);
 else
  if(select count(*)from users u join user_organization_scopes s on s.user_id=u.id where u.employee_record_id=i.employee_id and u.status='Active'and s.organization_id=i.organization_id and s.legal_entity_id=i.legal_entity_id and s.active)<>1 then raise exception 'The required affected worker relationship is unavailable.'using errcode='WGA05';end if;
  select u.id into worker_user from users u join user_organization_scopes s on s.user_id=u.id where u.employee_record_id=i.employee_id and u.status='Active'and s.organization_id=i.organization_id and s.legal_entity_id=i.legal_entity_id and s.active;
  select array_agg(distinct x)into expected_users from unnest(array[i.requester_user_id,worker_user])x;
 end if;
 if(select count(*)from work_approval_recipients where event_id=ev.id)<>cardinality(expected_users)then raise exception 'Canonical recipient set is incomplete or redirected.'using errcode='WGA05';end if;
 foreach u in array expected_users loop
  select * into r from work_approval_recipients where event_id=ev.id and user_id=u;
  expected_reasons=case when key='approval.action_required'then array['current_stage_approver']else array[]::text[]end;
  if key<>'approval.action_required'and u=i.requester_user_id then expected_reasons=array_append(expected_reasons,'requester');end if;
  if key<>'approval.action_required'and u=worker_user then expected_reasons=array_append(expected_reasons,'affected_worker');end if;
  if r.id is null or not(r.reasons@>expected_reasons and r.reasons<@expected_reasons)or(key<>'approval.completed'and(not r.in_app or r.channel_decision<>'Required'))then raise exception 'Protected in-app recipient/reason persistence must be atomic.'using errcode='WGA05';end if;
 end loop;
 if key in('approval.completed','approval.rejected_or_correction_required')and not exists(select 1 from work_submission_decisions d where d.submission_id=i.submission_id and d.status=last.decision and d.actor_id=last.actor_id)then raise exception 'Terminal work decision history is required.'using errcode='WGA05';end if;return null;
end $$;

create or replace function validate_assignment_approval_commit()returns trigger language plpgsql as $$
declare i assignment_approval_instances;p assignment_approval_policies;t assignment_approval_transitions;a project_allocations;seq integer;stage_no integer;key text;ev assignment_approval_events;worker_user uuid;users uuid[];u uuid;r assignment_approval_recipients;reasons text[];state text;
begin
 if tg_table_name='assignment_approval_instances'then i=new;seq=0;stage_no=0;key='approval.action_required';else select * into i from assignment_approval_instances where id=new.instance_id;seq=new.sequence;end if;
 select * into p from assignment_approval_policies where id=i.policy_id;select * into t from assignment_approval_transitions where instance_id=i.id order by sequence desc limit 1;select * into a from project_allocations where id=i.assignment_id;
 state=case when t.decision='Rejected'then'Rejected'when t.sequence=jsonb_array_length(p.definition->'stages')then'Approved'else'Pending'end;
 if not exists(select 1 from approval_records where entity_type='AssignmentProposal'and entity_id=i.id::text and status=state)then raise exception 'Compatibility approval must converge atomically.'using errcode='ASA04';end if;
 if i.operation_kind='Creation'then
  if state='Approved'then
   if assignment_version_snapshot(a)is distinct from jsonb_build_object('assignmentId',i.assignment_id,'employeeId',i.employee_id,'projectId',i.project_id)||i.proposed_definition or not exists(select 1 from assignment_versions v where v.assignment_id=i.assignment_id and v.organization_id=i.organization_id and v.legal_entity_id=i.legal_entity_id and v.sequence=1 and v.change_kind='Created'and v.source_revision=resource_assignment_revision(a)and v.actor_id=t.actor_id::text and v.reason=i.reason)or(select count(*)from assignment_versions where assignment_id=i.assignment_id)<>1 then raise exception 'Final creation and exact V1 must commit together.'using errcode='ASA04';end if;
  elsif a.id is not null or exists(select 1 from assignment_versions where assignment_id=i.assignment_id)then raise exception 'Non-final creation cannot allocate or reserve capacity.'using errcode='ASA04';end if;
 elsif state='Approved'then
  if assignment_version_snapshot(a)is distinct from i.before_snapshot||i.proposed_definition or not exists(select 1 from assignment_versions v where v.assignment_id=i.assignment_id and v.organization_id=i.organization_id and v.legal_entity_id=i.legal_entity_id and v.source_revision=resource_assignment_revision(a)and v.actor_id=t.actor_id::text and v.reason=i.reason)then raise exception 'Final assignment/version outcome must commit together.'using errcode='ASA04';end if;
 elsif resource_assignment_revision(a)is distinct from i.source_revision then raise exception 'Non-final assignment source must stay unchanged.'using errcode='ASA04';end if;
 if tg_table_name='assignment_approval_transitions'then stage_no=new.stage;if new.decision='Rejected'then key='approval.rejected_or_correction_required';elsif new.sequence<jsonb_array_length(p.definition->'stages')then key='approval.action_required';stage_no=new.sequence;else key='approval.completed';end if;end if;
 select * into ev from assignment_approval_events where instance_id=i.id and transition_sequence=seq and event_key=key;
 if key='approval.completed'and ev.id is null and exists(select 1 from assignment_approval_notification_failures where instance_id=i.id and transition_sequence=seq)then return null;end if;
 if ev.id is null or ev.stage<>stage_no or not exists(select 1 from assignment_approval_templates where id=ev.template_id and policy_id=p.id and event_key=key)then raise exception 'Canonical stage event/template is required.'using errcode='ASA04';end if;
 if key='approval.action_required'then users=canonical_stage_recipients(case when i.operation_kind='Creation'then'Creation'else'Material'end,i.id,stage_no,(p.definition->'stages'->stage_no->>'userId')::uuid,ev.created_at);else
  if(select count(*)from users u join user_organization_scopes s on s.user_id=u.id where u.employee_record_id=i.employee_id and u.status='Active'and s.organization_id=i.organization_id and s.legal_entity_id=i.legal_entity_id and s.active)<>1 then raise exception 'Affected worker relationship unavailable.'using errcode='ASA04';end if;
  select u.id into worker_user from users u join user_organization_scopes s on s.user_id=u.id where u.employee_record_id=i.employee_id and u.status='Active'and s.organization_id=i.organization_id and s.legal_entity_id=i.legal_entity_id and s.active;select array_agg(distinct x)into users from unnest(array[i.requester_user_id,worker_user])x;
 end if;
 if(select count(*)from assignment_approval_recipients where event_id=ev.id)<>cardinality(users)then raise exception 'Complete protected recipient set required.'using errcode='ASA04';end if;
 foreach u in array users loop
  select * into r from assignment_approval_recipients where event_id=ev.id and user_id=u;reasons=case when key='approval.action_required'then array['current_stage_approver']else array[]::text[]end;
  if key<>'approval.action_required'and u=i.requester_user_id then reasons=array_append(reasons,'requester');end if;if key<>'approval.action_required'and u=worker_user then reasons=array_append(reasons,'affected_worker');end if;
  if r.id is null or not(r.reasons@>reasons and r.reasons<@reasons)or(key<>'approval.completed'and(not r.in_app or r.channel_decision<>'Required'))or(r.in_app and not exists(select 1 from assignment_approval_deliveries where recipient_id=r.id))or(not r.in_app and exists(select 1 from assignment_approval_deliveries where recipient_id=r.id))then raise exception 'Complete canonical recipient/reason/delivery evidence required.'using errcode='ASA04';end if;
 end loop;return null;
end $$;

create or replace function validate_leave_approval_commit()returns trigger language plpgsql as $$
declare i leave_approval_instances;p leave_approval_policies;lr leave_requests;t leave_approval_transitions;seq integer;stage_no integer;key text;ev leave_approval_events;worker_user uuid;ids uuid[];u uuid;r leave_approval_recipients;reasons text[];state text;
begin
 if tg_table_name='leave_approval_policies'then
  if(select count(*)from leave_approval_templates where policy_id=new.id)<>3 then raise exception 'Retain all three canonical templates atomically.'using errcode='LGA04';end if;return null;
 elsif tg_table_name='leave_approval_instances'then i=new;seq=0;stage_no=0;key='approval.action_required';
 else select * into i from leave_approval_instances where id=new.instance_id;seq=new.sequence;stage_no=new.stage;end if;
 select * into p from leave_approval_policies where id=i.policy_id;select * into lr from leave_requests where id=i.request_id;
 select * into t from leave_approval_transitions where instance_id=i.id order by sequence desc limit 1;state=coalesce(t.outcome->>'status','Pending');
 if not exists(select 1 from approval_records where entity_type='LeaveRequest'and entity_id=i.request_id and status=case when state='Pending'then'Pending'else state end and due_at is null)or lr.status is distinct from(case when state='Pending'then'Submitted'else state end) or leave_source_snapshot(lr)is distinct from i.source_snapshot then raise exception 'Exact leave source and compatibility outcome must converge atomically.'using errcode='LGA04';end if;
 if tg_table_name='leave_approval_transitions'then
  if new.decision='Rejected'then key='approval.rejected_or_correction_required';elsif new.sequence<jsonb_array_length(p.definition->'stages')then key='approval.action_required';stage_no=new.sequence;else key='approval.completed';end if;
 end if;
 select * into ev from leave_approval_events where instance_id=i.id and transition_sequence=seq and event_key=key;
 if key='approval.completed'and ev.id is null and exists(select 1 from leave_approval_notification_failures where instance_id=i.id and transition_sequence=seq)then return null;end if;
 if ev.id is null or ev.stage<>stage_no or not exists(select 1 from leave_approval_templates where id=ev.template_id and policy_id=p.id and event_key=key and locale=ev.locale)then raise exception 'Canonical leave stage event and retained template required.'using errcode='LGA04';end if;
 if key='approval.action_required'then ids=canonical_stage_recipients('Leave',i.id,stage_no,(p.definition->'stages'->stage_no->>'userId')::uuid,ev.created_at);else
  if(select count(*)from users w join user_organization_scopes sc on sc.user_id=w.id where w.employee_record_id=i.employee_id and w.status='Active'and sc.organization_id=i.organization_id and sc.legal_entity_id=i.legal_entity_id and sc.active)<>1 then raise exception 'Affected leave worker account unavailable.'using errcode='LGA04';end if;
  select w.id into worker_user from users w join user_organization_scopes sc on sc.user_id=w.id where w.employee_record_id=i.employee_id and w.status='Active'and sc.organization_id=i.organization_id and sc.legal_entity_id=i.legal_entity_id and sc.active;
  select array_agg(distinct x)into ids from unnest(array[i.requester_user_id,worker_user])x;
 end if;
 if(select count(*)from leave_approval_recipients where event_id=ev.id)<>cardinality(ids)then raise exception 'Complete canonical leave recipient set required.'using errcode='LGA04';end if;
 foreach u in array ids loop
  select * into r from leave_approval_recipients where event_id=ev.id and user_id=u;reasons=case when key='approval.action_required'then array['current_stage_approver']else array[]::text[]end;
  if key<>'approval.action_required'and u=i.requester_user_id then reasons=array_append(reasons,'requester');end if;if key<>'approval.action_required'and u=worker_user then reasons=array_append(reasons,'affected_worker');end if;
  if r.id is null or not(r.reasons@>reasons and r.reasons<@reasons)or(key<>'approval.completed'and(not r.in_app or r.channel_decision<>'Required'))or(r.in_app and not exists(select 1 from leave_approval_deliveries where recipient_id=r.id))or(not r.in_app and exists(select 1 from leave_approval_deliveries where recipient_id=r.id))then raise exception 'Complete atomic leave recipient, reason and accepted delivery required.'using errcode='LGA04';end if;
 end loop;return null;
end $$;

create function guard_canonical_delegate_decision()returns trigger language plpgsql as $$declare b canonical_delegation_bindings;s record;t record;begin
 select * into b from canonical_delegation_bindings where id=new.binding_id;if b.id is null or b.origin<>new.origin then raise exception 'Exact delegate decision binding required.'using errcode='CDG03';end if;
 if new.origin='Work'then select instance_id,stage,actor_id,xmin::text xid into t from work_approval_transitions where id=new.transition_id;elsif new.origin='Leave'then select instance_id,stage,actor_id,xmin::text xid into t from leave_approval_transitions where id=new.transition_id;else select instance_id,stage,actor_id,xmin::text xid into t from assignment_approval_transitions where id=new.transition_id;end if;
 select * into s from canonical_delegation_source(b.origin,b.instance_id);
 if t.xid is distinct from pg_current_xact_id()::text or t.instance_id is distinct from b.instance_id or t.stage is distinct from b.stage or t.actor_id is distinct from new.actor_id or t.actor_id::text=s.stages->b.stage->>'userId'or not canonical_stage_actor(b.origin,b.instance_id,b.stage,(s.stages->b.stage->>'userId')::uuid,t.actor_id,s.stages->b.stage->>'role')then raise exception 'Retain only the actual same-transaction current delegated transition.'using errcode='CDG03';end if;return new;
end $$;
create trigger guarded_canonical_delegate_decisions before insert on canonical_delegation_decisions for each row execute function guard_canonical_delegate_decision();
